void chineseText(Adafruit_GFX& display, int16_t x, int16_t y, const char* value, uint16_t color) {
  while (*value) { uint32_t code = static_cast<uint8_t>(*value++); if ((code & 0xE0) == 0xC0) { const uint8_t next = static_cast<uint8_t>(*value++); code = ((code & 0x1F) << 6) | (next & 0x3F); } else if ((code & 0xF0) == 0xE0) { const uint8_t next = static_cast<uint8_t>(*value++); const uint8_t last = static_cast<uint8_t>(*value++); code = ((code & 0x0F) << 12) | ((next & 0x3F) << 6) | (last & 0x3F); } const uint8_t* data = nullptr; for (const auto& glyph : glyphs) if (glyph.code == code) data = glyph.data; if (data) { display.drawBitmap(x, y, data, 16, 16, color); x += 16; } else { x += 8; } }
}
void chineseTextSmall(Adafruit_GFX& display, int16_t x, int16_t y, const char* value, uint16_t color) {
  while (*value) { uint32_t code = static_cast<uint8_t>(*value++); if ((code & 0xE0) == 0xC0) { const uint8_t next = static_cast<uint8_t>(*value++); code = ((code & 0x1F) << 6) | (next & 0x3F); } else if ((code & 0xF0) == 0xE0) { const uint8_t next = static_cast<uint8_t>(*value++); const uint8_t last = static_cast<uint8_t>(*value++); code = ((code & 0x0F) << 12) | ((next & 0x3F) << 6) | (last & 0x3F); } const uint8_t* data = nullptr; for (const auto& glyph : glyphs) if (glyph.code == code) data = glyph.data; if (data) { for (uint8_t row = 0; row < 8; ++row) { const uint8_t sourceRow = row * 2; for (uint8_t col = 0; col < 8; ++col) { const uint8_t sourceCol = col * 2; const uint8_t byte = data[sourceRow * 2 + sourceCol / 8]; if (byte & (1 << (7 - (sourceCol % 8)))) display.drawPixel(x + col, y + row, color); } } x += 10; } else { x += 6; } }
}
